"use client";

import "../../styles/whatiuse-base.css";
import "../../styles/components/select.css";
import { Check, CaretDown } from "@phosphor-icons/react";
import { Select as SelectPrimitive } from "@base-ui/react/select";
import { useId } from "react";
import { cn } from "../../lib/cn";

export type SelectOption = { label: string; value: string; disabled?: boolean };

export type SelectProps = Omit<SelectPrimitive.Root.Props<string>, "children" | "items" | "aria-label"> & {
  label?: string;
  "aria-label"?: string;
  description?: string;
  error?: string;
  placeholder?: string;
  options: readonly SelectOption[];
  className?: string;
  ref?: SelectPrimitive.Trigger.Props["ref"];
};

export function Select({ label, "aria-label": ariaLabel, description, error, placeholder = "Select an option", options, className, ref, ...props }: SelectProps) {
  const id = useId();
  const descriptionId = description ? `${id}-description` : undefined;
  const errorId = error ? `${id}-error` : undefined;
  return (
    <div className="whatiuse-field whatiuse-select-field" data-invalid={Boolean(error) || undefined}>
      <SelectPrimitive.Root items={options} {...props}>
        {label && <SelectPrimitive.Label className="whatiuse-field__label">{label}</SelectPrimitive.Label>}
        <SelectPrimitive.Trigger ref={ref} className={cn("whatiuse-select", className)} aria-label={label ? undefined : ariaLabel} aria-describedby={[descriptionId, errorId].filter(Boolean).join(" ") || undefined} aria-invalid={Boolean(error) || undefined}>
          <SelectPrimitive.Value className="whatiuse-select__value" placeholder={placeholder} />
          <SelectPrimitive.Icon className="whatiuse-select__icon"><CaretDown aria-hidden="true" /></SelectPrimitive.Icon>
        </SelectPrimitive.Trigger>
        <SelectPrimitive.Portal>
          <SelectPrimitive.Positioner className="whatiuse-positioner" sideOffset={5} align="start" alignItemWithTrigger={false}>
            <SelectPrimitive.Popup className="whatiuse-select-popup" data-layer="flyout">
              <SelectPrimitive.List className="whatiuse-select-list" aria-label={`${label ?? ariaLabel ?? "Select"} options`}>
                {options.map((option) => (
                  <SelectPrimitive.Item className="whatiuse-select-item" key={option.value} value={option.value} disabled={option.disabled}>
                    <SelectPrimitive.ItemText>{option.label}</SelectPrimitive.ItemText>
                    <SelectPrimitive.ItemIndicator className="whatiuse-select-item__indicator"><Check weight="bold" /></SelectPrimitive.ItemIndicator>
                  </SelectPrimitive.Item>
                ))}
              </SelectPrimitive.List>
            </SelectPrimitive.Popup>
          </SelectPrimitive.Positioner>
        </SelectPrimitive.Portal>
      </SelectPrimitive.Root>
      {description && <div id={descriptionId} className="whatiuse-field__description">{description}</div>}
      {error && <div id={errorId} className="whatiuse-field__error">{error}</div>}
    </div>
  );
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer whatiuse.tokens, whatiuse.base, whatiuse.components;

@layer whatiuse.components {
.whatiuse-select-field { min-width: 240px; }

.whatiuse-select {
  display: inline-flex;
  width: 100%;
  min-width: 180px;
  height: 32px;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 0 9px 0 10px;
  border: 1px solid var(--whatiuse-border);
  border-radius: var(--whatiuse-radius-sm);
  background: var(--whatiuse-control-surface);
  box-shadow: var(--whatiuse-shadow-control);
  color: var(--whatiuse-ink);
  font: inherit;
  font-size: var(--whatiuse-type-ui);
  cursor: pointer;
  transition: border-color var(--whatiuse-hover-duration) ease, box-shadow var(--whatiuse-hover-duration) ease, transform var(--whatiuse-press-duration) var(--whatiuse-ease-out, ease-out);
}

.whatiuse-select[data-placeholder] .whatiuse-select__value { color: var(--whatiuse-ink-tertiary); }

.whatiuse-select[data-disabled] { color: var(--whatiuse-ink-disabled); cursor: not-allowed; background: var(--whatiuse-gray-50); box-shadow: none; }

.whatiuse-select:focus-visible { outline: 0; border-color: var(--whatiuse-control-border-hover); box-shadow: var(--whatiuse-shadow-control); }

.whatiuse-select__icon,
.whatiuse-select__icon svg { width: 13px; height: 13px; color: var(--whatiuse-ink-tertiary); }

.whatiuse-select-popup {
  min-width: var(--anchor-width);
  max-height: min(320px, var(--available-height));
  overflow: hidden;
  border: 1px solid var(--whatiuse-border);
  border-radius: var(--whatiuse-radius-md);
  background: var(--whatiuse-bg-flyout);
  box-shadow: var(--whatiuse-shadow-flyout);
  color: var(--whatiuse-ink);
  transform-origin: var(--transform-origin);
  transition: opacity var(--whatiuse-flyout-enter-duration) var(--whatiuse-ease-out, ease-out), transform var(--whatiuse-flyout-enter-duration) var(--whatiuse-ease-out, ease-out);
}

.whatiuse-select-popup[data-starting-style] { opacity: 0; transform: translateY(-2px) scale(0.99); }

.whatiuse-select-popup[data-ending-style] { opacity: 0; transform: translateY(-1px) scale(0.995); }

.whatiuse-select-popup[data-ending-style] { transition-duration: var(--whatiuse-flyout-exit-duration); }

.whatiuse-select-popup:focus-visible,
.whatiuse-select-item:focus-visible { outline: 0; }

.whatiuse-select-list { padding: 4px; overflow-y: auto; }

.whatiuse-select-item {
  display: flex;
  min-height: 30px;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 5px 7px;
  border-radius: 5px;
  color: var(--whatiuse-ink-secondary);
  font-size: var(--whatiuse-type-ui);
  outline: none;
  cursor: default;
}

.whatiuse-select-item[data-highlighted] { background: var(--whatiuse-hover); color: var(--whatiuse-ink); }

.whatiuse-select-item[data-disabled] { color: var(--whatiuse-ink-disabled); }

.whatiuse-select-item__indicator { display: grid; width: 14px; height: 14px; flex: 0 0 auto; place-items: center; }

.whatiuse-select-item__indicator svg { width: 12px; height: 12px; }

@media (hover: hover) and (pointer: fine) {
.whatiuse-select:not([data-disabled]):hover { border-color: var(--whatiuse-border-strong); }
}

.whatiuse-positioner { z-index: var(--whatiuse-layer-flyout); }

.whatiuse-field { display: grid; min-width: 0; gap: 6px; }

.whatiuse-field__label { color: var(--whatiuse-ink); font-size: 12px; font-weight: 550; }

.whatiuse-field[data-invalid] .whatiuse-field__control { border-color: color-mix(in oklch, var(--whatiuse-fg-danger) 46%, var(--whatiuse-control-border)); box-shadow: 0 0 0 2px color-mix(in oklch, var(--whatiuse-fg-danger) 11%, transparent); }

.whatiuse-field__description,
.whatiuse-field__error { color: var(--whatiuse-ink-tertiary); font-size: 11.5px; line-height: 1.45; }

.whatiuse-field__error { color: var(--whatiuse-fg-danger); font-weight: 520; }

.whatiuse-select-popup {
  scrollbar-color: var(--whatiuse-scrollbar-thumb) transparent;
  scrollbar-width: thin;
}

.whatiuse-select-popup::-webkit-scrollbar { width: 10px; height: 10px; }

.whatiuse-select-popup::-webkit-scrollbar-track { background: transparent; }

.whatiuse-select-popup::-webkit-scrollbar-thumb {
  border: 3px solid transparent;
  border-radius: 999px;
  background: var(--whatiuse-scrollbar-thumb);
  background-clip: padding-box;
}

.whatiuse-select-popup::-webkit-scrollbar-thumb:hover { background: var(--whatiuse-scrollbar-thumb-hover); background-clip: padding-box; }

:root[data-theme="dark"] .whatiuse-select[data-disabled] { background: rgb(255 255 255 / 0.025); color: var(--whatiuse-ink-disabled); }

.whatiuse-select-item__indicator {
  opacity: 1;
  transform: scale(1);
  transition: opacity 140ms var(--whatiuse-ease-out), transform 140ms var(--whatiuse-ease-out);
}

@starting-style {
.whatiuse-select-item__indicator {
    opacity: 0;
    transform: scale(.9);
  }
}

.whatiuse-select__icon svg {
  transform-origin: center;
  transition: transform 160ms var(--whatiuse-ease-out);
}

.whatiuse-select[data-popup-open] .whatiuse-select__icon svg {
  transform: rotate(180deg);
}

.whatiuse-select-popup { background: var(--whatiuse-bg-flyout); }

@media (forced-colors: active) {
.whatiuse-select-popup { scrollbar-color: auto; }
}

@media (prefers-reduced-motion: reduce) {
.whatiuse-select-popup {
    transition-property: opacity;
    transition-duration: var(--whatiuse-exit-duration);
  }

.whatiuse-select-popup[data-starting-style],
.whatiuse-select-popup[data-ending-style] { transform: none; }

.whatiuse-select:active { transform: none; }

.whatiuse-select__icon svg,
.whatiuse-select-item__indicator { transition-duration: 0.01ms; }
}
}
